import * as M from './model.js?v=20261009-tree-5';
import {gateway, allowed} from './cloud.js?v=20261009-tree-5';

const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy = value => JSON.parse(JSON.stringify(value));
const number = value => value === '' || value == null ? null : Number(value);
const total = list => list.reduce((a,b) => a + (Number(b) || 0), 0);
const records = kind => kind === 'recruiting' ? (Array.isArray(draft.recruiting) ? draft.recruiting : draft.recruiting?.rows || []) : draft[kind] || [];
const setRecords = (kind,rows) => {if(kind!=='recruiting'){draft[kind]=rows;return;}draft.recruiting=M.recruitingSummary({...(!Array.isArray(draft.recruiting)&&draft.recruiting||{}),rows});};
const fmt = (v, digits = 0) => v == null || !Number.isFinite(Number(v)) ? '—' : Number(v).toLocaleString('ko-KR', {maximumFractionDigits:digits});
const avgFmt = v => v == null || !Number.isFinite(Number(v)) ? '—' : Number(v).toLocaleString('ko-KR',{minimumFractionDigits:2,maximumFractionDigits:2});
const pct = v => v == null ? 'N/A' : `${fmt(v,1)}%`;
const money = v => v == null ? '—' : `${fmt(v)}원`;
const ratio = (a,b) => a != null && b > 0 ? a/b*100 : null;
const newId = () => globalThis.crypto?.randomUUID?.() || `recap-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const chapters = [['PERFORMANCE','팀 세일즈 분석'],['RECRUITING','팀 리쿠르팅 분석'],['QUALITY CONTROL','팀원 QC · In & Out'],['WIN & HOW','Win & HOW'],['CHALLENGES','챌린지 & 개선 액션'],['LEARNING PLAN','러닝 플랜'],['TEAM TREE','팀 트리'],['PROMOTION GOAL','프로모션 골'],['OVERVIEW','전체 종합']];
const baseViews = [{id:'sales',c:0,title:'팀원별 성과 한눈에'},{id:'weekly',c:0,title:'주차별 실적'},{id:'income',c:0,title:'인컴 랭킹'},{id:'recruit',c:1,title:'리쿠르팅 퍼널'},{id:'rank',c:1,title:'리쿠르팅 랭킹'},{id:'qc',c:2,title:'In · Out & 유지'},{id:'wins',c:3,title:'Win & HOW'},{id:'challenges',c:4,title:'챌린지 & 개선 액션'},{id:'callback',c:5,title:'콜백싯 제출률'},{id:'learning',c:5,title:'학습 & 다음 달 계획'},{id:'ic',c:5,title:'IC 성장 플랜'},{id:'tree',c:6,title:'팀 트리'},{id:'promotion',c:7,title:'프로모션 골'},{id:'overview',c:8,title:'전체 종합'}];
let views=[{id:'cover',c:-1,title:'표지',key:'cover'},{id:'contents',c:-1,title:'목차',key:'contents'},...baseViews.map(v=>({...v,key:v.id+':0'}))];
const params = new URLSearchParams(location.search);
const isViewer=location.pathname.endsWith('/recap-view.html');
if(!isViewer&&(params.has('published')||params.has('present'))){const target=new URL('recap-view.html',location.href);target.search=location.search;location.replace(target);}
const now = new Date();
const defaultMonth = `${now.getMonth() === 0 ? now.getFullYear()-1 : now.getFullYear()}-${String(now.getMonth() === 0 ? 12 : now.getMonth()).padStart(2,'0')}`;
let month = /^\d{4}-(0[1-9]|1[0-2])$/.test(params.get('month') || '') ? params.get('month') : defaultMonth;
let user, api, draft, liveSource, page = 0, dirty = false, saving = false, editing = false, presenting = false, readOnly = isViewer || params.has('published');
let pendingModal = null, dialogOrigin = null, noticeMessages = [], loadToken = 0, changeVersion = 0, toastTimer;
const view = () => views[page];
const monthName = () => `${month.slice(0,4)}년 ${Number(month.slice(5))}월`;
const knownIncome = () => (draft.members||[]).some(m=>(m.incomeWeeks||[]).some(v=>v!=null)) ? totals().knownIncome : null;
const missingIncome = () => (draft.members||[]).reduce((n,m)=>n+(m.incomeWeeks||[]).filter(v=>v==null).length,0);
const nextMonthName = () => {const dt = new Date(Number(month.slice(0,4)), Number(month.slice(5)), 1); return `${dt.getFullYear()}년 ${dt.getMonth()+1}월`;};
const backupKey = () => `presence-recap-keynote:${user?.uid || user?.id || user?.name}:${month}`;
const metrics = m => {
  const a = M.memberMetric(m);
  return {...a, rate:a.rejectRate ?? a.rate ?? null, raw:a.rawReject ?? a.raw ?? null, alert:(a.rejectRate ?? a.rate ?? 0) > 35};
};
const totals = () => {const a = M.totals(draft); return {...a,rate:a.rejectRate ?? a.rate ?? null,weeks:a.weekly ?? a.weeks ?? []};};
const callbackRows = () => (draft.members || []).map(m => ({...m,days:Number(m.days)||0,submitted:number(draft.callbacks?.[m.id]),rate:ratio(number(draft.callbacks?.[m.id]),Number(m.days)||0)}));
const callbackSummary = () => {const rows=callbackRows();const days=total(rows.map(r=>r.days)),submitted=total(rows.map(r=>r.submitted)),missing=rows.filter(r=>r.days>0&&r.submitted==null).length;return {rows,days,submitted,rate:missing?null:ratio(submitted,days),missing};};
const sortedMembers = () => [...(draft.members||[])].sort((a,b)=>(metrics(b).sales||0)-(metrics(a).sales||0));
const bar = (value,max=100,color='') => `<div class="bar-track"><div class="bar-fill ${color}" style="width:${Math.max(0,Math.min(100,(Number(value)||0)/Math.max(1,max)*100))}%"></div></div>`;
const empty = (title,body,action='edit') => `<div class="empty"><strong>${esc(title)}</strong><span>${esc(body)}</span>${(!readOnly||action==='retry-load')&&!presenting?`<button data-action="${action}">내용 입력하기</button>`:''}</div>`;
const kpi = (label,value,sub='',cls='') => `<div class="kpi ${cls}"><span>${esc(label)}</span><b>${esc(value)}</b><small>${esc(sub)}</small></div>`;
const tag = (text,cls='') => text ? `<span class="tag ${cls}">${esc(text)}</span>` : '';
const textBox = (title,text) => `<div class="text-box"><h3>${esc(title)}</h3><p>${esc(text||'아직 기록하지 않았습니다.')}</p></div>`;
const table = (heads,rows,foot='') => `<div class="table-wrap"><table class="data-table"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody>${foot?`<tfoot>${foot}</tfoot>`:''}</table></div>`;
const person = m => `<b class="${metrics(m).alert?'danger':''}">${esc(m.name)}</b><span class="role">${esc(m.role||'')}</span>`;
const desc = {callback:'제출률 = 콜백싯 제출 횟수 ÷ 필드일수 · 팀 합계 기준'};


const INTRO=[{id:'cover',c:-1,title:'표지',key:'cover'},{id:'contents',c:-1,title:'목차',key:'contents'}];
const batches=(items,size)=>items.length?Array.from({length:Math.ceil(items.length/size)},(_,i)=>items.slice(i*size,(i+1)*size)):[[]];
function textParts(value,size=300){let rest=String(value||''),parts=[];while(rest.length){let cut=Math.min(size,rest.length);if(cut<rest.length){const space=rest.lastIndexOf(' ',cut);if(space>cut*.6)cut=space+1;}parts.push(rest.slice(0,cut));rest=rest.slice(cut);}return parts.length?parts:[''];}
function narrativeParts(items,keys,budget=280){return items.flatMap(item=>{const data=keys.map(k=>[k,String(item[k]||'')]),length=total(data.map(x=>x[1].length));if(length<=budget)return[{...item,continuation:0}];let pages=[],current={...item,continuation:0},remaining=budget;keys.forEach(k=>current[k]='');for(const [key,value]of data){let rest=value;while(rest){if(!remaining){pages.push(current);current={...item,continuation:pages.length};keys.forEach(k=>current[k]='');remaining=budget;}const chunk=rest.slice(0,remaining);current[key]+=chunk;rest=rest.slice(chunk.length);remaining-=chunk.length;}}pages.push(current);return pages;});}
function callbackPages(){const grouped=new Map();for(const row of callbackRows()){const name=row.team||'팀 미지정';if(!grouped.has(name))grouped.set(name,[]);grouped.get(name).push(row);}return [...grouped].flatMap(([name,all])=>batches(all,6).map((rows,i)=>({name,rows,all,part:i,totalParts:Math.ceil(all.length/6)})));}
function incomeMembers(){return [...(draft.members||[])].sort((a,b)=>(metrics(b).income??-1)-(metrics(a).income??-1));}
function rebuildViews(){if(!draft)return;const previous=views[page]?.key,newViews=INTRO.map(x=>({...x}));const add=(base,sets,extra={})=>{sets.forEach((items,i)=>newViews.push({...base,...extra,items,key:base.id+':'+(extra.kind||'main')+':'+i,part:i,parts:sets.length}));};
for(const base of baseViews){if(['sales','weekly','income','rank'].includes(base.id)){const items=base.id==='income'?incomeMembers():base.id==='rank'?[...recruiting().rows].sort((a,b)=>b.starters-a.starters||b.showup-a.showup||b.booked-a.booked):sortedMembers();add(base,batches(items,9));}
else if(base.id==='qc'){add(base,batches(narrativeParts(draft.events||[],['reason','action'],110),6));if(draft.qc?.retentionWin||draft.qc?.trainingHow)add(base,textParts([draft.qc.retentionWin&&'유지에 도움이 된 WIN\n'+draft.qc.retentionWin,draft.qc.trainingHow&&'교육 · 유지 활동 HOW\n'+draft.qc.trainingHow].filter(Boolean).join('\n\n'),450),{kind:'note',noteTitle:'교육과 유지의 기록'});}
else if(['wins','challenges'].includes(base.id))add(base,batches(draft[base.id]||[],3));
else if(base.id==='learning'){newViews.push({...base,title:nextMonthName()+' 목표',kind:'goals',key:'learning-goals',items:[]});if((draft.learning||[]).some(x=>x.result||x.action?.length>60||x.period==='지난달 회고'))add(base,batches(narrativeParts(draft.learning||[],['action','result'],220),3));}
else if(base.id==='callback')add(base,batches(callbackPages(),3));
else if(base.id==='ic'){const people=icMembers();if(!people.length)add(base,[[]]);else people.forEach((person,i)=>{newViews.push({...base,items:[person],key:'ic:'+person.id,part:i,parts:people.length});const p=draft.icPlans?.[person.id]||{},detail=[p.focus&&'집중 역량\n'+p.focus,...[1,2,3].map(n=>p['day'+n]&&'DAY '+n+'\n'+p['day'+n])].filter(Boolean).join('\n\n');if(detail.length>450||[1,2,3].some(n=>p['day'+n]?.length>70))textParts(detail,480).forEach((text,k)=>newViews.push({...base,kind:'note',noteTitle:person.name+' · 3일 성장 플랜',items:text,key:'ic-note:'+person.id+':'+k,part:k,parts:Math.ceil(detail.length/480)}));});}
else if(base.id==='tree'){const large=(draft.tree||[]).length>14||treeGroups().length>6;add(base,large?batches(draft.tree,8):[draft.tree||[]],{treeRows:large});}
else if(base.id==='promotion'){const expanded=(draft.promotions||[]).flatMap(p=>{const actions=textParts(p.action,200),checks=batches(p.checks||[],6);return Array.from({length:Math.max(actions.length,checks.length)},(_,i)=>({...p,action:actions[i]||'',checks:checks[i]||[],continuation:i}));});add(base,batches(expanded,2));}
else add(base,[[]]);
if(base.id==='sales'&&draft.notes?.sales)add(base,textParts(draft.notes.sales,480),{kind:'note',noteTitle:'세일즈 회고'});
if(base.id==='recruit'&&draft.notes?.recruit)add(base,textParts(draft.notes.recruit,480),{kind:'note',noteTitle:'리쿠르팅 회고'});
}
views=newViews;const index=views.findIndex(v=>v.key===previous);page=index>=0?index:Math.min(page,views.length-1);}
function renderCover(){const weeks=draft.weeks||[],first=weeks[0]||{},last=weeks.at(-1)||{},range=(start,end)=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(start||'')||!/^\d{4}-\d{2}-\d{2}$/.test(end||''))return '미확인';return start.replaceAll('-','.')+'–'+(start.slice(0,4)===end.slice(0,4)?end.slice(5):end).replaceAll('-','.');};return `<div class="cover-slide"><div class="cover-copy"><span class="eyebrow">PRESENCE · TEAM RECAP</span><p class="cover-month">${esc(month.slice(0,4))}</p><h1>${Number(month.slice(5))}월 리캡</h1><div class="cover-dates"><p><span>필드</span><b>${esc(range(first.start,last.end))}</b></p><p><span>지급</span><b>${esc(range(first.pay,last.pay))}</b></p></div><div class="cover-author">${esc(draft.teamName||'Presence')}<br><span>${esc(draft.leader||'')}</span></div></div><div class="cover-geometry"><div class="cover-period"><small>${esc(month.slice(0,4))}</small><strong>${esc(month.slice(5))}</strong><span>MONTHLY RECAP</span></div><span class="cover-orbit" aria-hidden="true"></span><i aria-hidden="true"></i><i aria-hidden="true"></i><i aria-hidden="true"></i></div></div>`;}
function renderContents(){return `<div class="contents-grid">${chapters.map(([en,title],c)=>`<button class="contents-item" data-action="chapter" data-index="${c}"><span class="contents-index">${String(c+1).padStart(2,'0')}</span><span><strong>${title}</strong><small>${en}</small></span><span class="contents-arrow" aria-hidden="true">↗</span></button>`).join('')}</div>`;}
function renderNote(){return `<section class="narrative-page"><span class="tag">${esc(view().noteTitle||'이어지는 기록')}</span><p>${esc(view().items||'기록된 내용이 없습니다.')}</p></section>`;}
function pageCaption(){const v=view();return v.parts>1?`${v.part+1} / ${v.parts}`:'';}

function shortDate(value){const m=String(value||'').match(/^(?:\d{4}-)?(\d{2})-(\d{2})$/);return m?Number(m[1])+'/'+Number(m[2]):'미확인';}
function salesSubtitle(){const weeks=draft.weeks||[];return `${(draft.members||[]).length}명 통합 비교 · 세일즈 높은 순 · 필드 ${shortDate(weeks[0]?.start)}–${shortDate(weeks.at(-1)?.end)}, 지급 ${shortDate(weeks[0]?.pay)}–${shortDate(weeks.at(-1)?.pay)}`;}
function performanceBar(value,max,avg=false,reference=null){const width=Math.max(0,Math.min(100,(Number(value)||0)/Math.max(1,max)*100)),ref=reference==null?null:reference/Math.max(1,max)*100;return `<div class="metric-bar-lane ${avg?'avg-bar-lane':''}"><span class="${avg?'avg-fill':'sales-bar'}" style="width:${width}%"></span><b class="metric-bar-value" style="left:calc(${width}% + 8px)" data-counter>${avg?avgFmt(value):fmt(value)}</b>${ref==null?'':`<i class="avg-reference" style="left:${ref}%" aria-label="팀 AVG ${avgFmt(reference)}"></i>`}</div>`;}
function renderSales(){const t=totals(),all=sortedMembers(),members=view().items||all,max=Math.max(1,...all.map(m=>metrics(m).sales||0)),avgMax=Math.max(1,t.avg||0,...all.map(m=>metrics(m).avg||0));if(!members.length)return empty('이달 워크북 기록이 없습니다.','문서 메뉴에서 워크북 수치를 새로 불러올 수 있습니다.','refresh');const body=table(['팀원','필드일','세일즈 (건)','AVG (건/일)','실인컴','리젝','리젝률'],members.map(m=>{const a=metrics(m);return `<tr><td>${person(m)}</td><td>${fmt(a.days)}</td><td>${performanceBar(a.sales,max)}</td><td>${performanceBar(a.avg,avgMax,true,t.avg)}</td><td>${money(a.income)}${a.incomeComplete===false?' *':''}</td><td>${fmt(a.reject)}</td><td class="${a.alert?'danger':''}">${pct(a.rate)}</td></tr>`;}),`<tr><td>팀 합계</td><td>${fmt(t.days)}</td><td>${fmt(t.sales)}</td><td>${avgFmt(t.avg)}</td><td class="income-total">${money(t.incomeComplete===false?knownIncome():t.income)}${t.incomeComplete===false?' *':''}</td><td>${fmt(t.reject)}</td><td>${pct(t.rate)}</td></tr>`).replace('class="data-table"','class="data-table sales-overview-table"');return body+`<p class="table-note sales-reference-note"><span>관리 필요: 리젝률 35% 초과(붉은색)</span> · AVG 점선 = 팀 평균 ${avgFmt(t.avg)} · 리젝은 리섭 차감 후 기준${t.incomeComplete===false?' · * 일부 급여 주차 미입력':''}</p>`;}
function weekLabels(){return (draft.weeks||[]).map((w,i)=>({label:`W${i+1}`,date:typeof w==='string'?w:`필드 ${[w.start||w.startDate,w.end||w.endDate].filter(Boolean).join(' ~ ')}${w.pay?` / 급여일 ${w.pay}`:''}`,raw:w}));}
function renderWeekly(){const weeks=weekLabels(),all=sortedMembers(),members=view().items||all,sums=weeks.map((_,i)=>total(all.map(m=>m.scores?.[i]))),max=Math.max(1,...sums);if(!weeks.length)return empty('주차 기록이 없습니다.','워크북 수치를 불러오면 주차별 실적이 표시됩니다.','refresh');return `<div class="weekly-layout"><section class="panel"><h3>주차별 팀 세일즈</h3><div class="week-bars">${weeks.map((w,i)=>`<div class="week-bar"><strong data-counter>${fmt(sums[i])}</strong><i class="weekly-fill" style="--week-ratio:${sums[i]/max};height:${Math.max(3,sums[i]/max*270)}px"></i><span>${w.label}</span></div>`).join('')}</div></section><section>${table(['팀원',...weeks.map(w=>w.label),'합계'],members.map(m=>`<tr><td>${person(m)}</td>${weeks.map((_,i)=>`<td>${fmt(m.scores?.[i])}</td>`).join('')}<td><b>${fmt(metrics(m).sales)}</b></td></tr>`),`<tr><td>팀 합계</td>${sums.map(n=>`<td>${fmt(n)}</td>`).join('')}<td>${fmt(total(sums))}</td></tr>`)}</section></div>`;}

function renderIncome(){const t=totals(),all=incomeMembers(),members=view().items||all,max=Math.max(1,...all.map(m=>metrics(m).income||0)),offset=(view().part||0)*9;return `<section class="income-full"><div class="income-banner"><div><span class="eyebrow">${t.incomeComplete===false?'확인된 인컴':'TEAM INCOME'}</span><strong data-counter>${money(t.incomeComplete===false?knownIncome():t.income)}</strong></div><p>${t.incomeComplete===false?`미입력 급여 기록 ${missingIncome()}개 · 최종 인컴은 달라질 수 있습니다.`:'입력된 급여 주차의 합계 · 개인별 월간 인컴 순위'}</p></div><div class="income-rank-wide">${members.map((m,i)=>{const a=metrics(m);return `<div class="rank-row-wide"><span class="rank-num">${String(offset+i+1).padStart(2,'0')}</span><div class="rank-person"><b class="${a.alert?'danger':''}">${esc(m.name)}</b><small>${esc(m.role||'')}</small></div>${bar(a.income,max,i+offset===0?'':'pale')}<strong data-counter>${money(a.income)}${a.incomeComplete===false?' *':''}</strong></div>`;}).join('')||empty('입력된 팀원이 없습니다.','이달의 인컴 기록이 없습니다.')}</div></section>`;}

function recruiting(){const r=M.recruitingSummary(draft.recruiting);return {...r,rows:r.rows,booked:r.booking,starters:r.starter};}
function renderRecruit(rank=false){const r=recruiting(),rows=view().items||r.rows;return rank?(rows.length?table(['랭킹 · 팀원','부킹','쇼업','스타터'],rows.map((row,i)=>`<tr><td><span class="role">${(view().part||0)*9+i+1}</span> <b>${esc(row.name)}</b></td><td>${fmt(row.booked)}</td><td>${fmt(row.showup)}</td><td><b>${fmt(row.starters)}</b></td></tr>`),`<tr><td>팀 합계</td><td>${fmt(r.booked)}</td><td>${fmt(r.showup)}</td><td>${fmt(r.starters)}</td></tr>`):empty('리쿠르팅 실적을 입력해 주세요.','부킹 · 쇼업 · 스타터를 기록합니다.')):`<div class="funnel">${[['BOOKING',r.booked,'부킹'],['SHOW UP',r.showup,'쇼업'],['STARTER',r.starters,'스타터']].map(([en,n,ko])=>`<div class="funnel-step"><small>${en}</small><b data-counter>${fmt(n)}</b><p>${ko}</p></div>`).join('')}</div><div class="recruit-conversions"><div><span>부킹 → 쇼업</span><b data-counter>${pct(ratio(r.showup,r.booked))}</b><p>참석으로 이어진 예약 비율</p></div><div><span>쇼업 → 스타터</span><b data-counter>${pct(ratio(r.starters,r.showup))}</b><p>첫필드로 이어진 참석 비율</p></div></div><p class="table-note">개인별 기록은 다음 리쿠르팅 랭킹 페이지에서 확인합니다.${draft.notes?.recruit?' 이어지는 페이지에 회고가 있습니다.':''}</p>`;}

function renderQC(){const all=draft.events||[],events=view().items||all,ins=number(draft.qc?.inCount)??all.filter(e=>e.type==='In').length,outs=number(draft.qc?.outCount)??all.filter(e=>e.type!=='In').length,start=number(draft.qc?.startCount);return `<div class="flow-line"><div><small>월초 인원</small><b>${fmt(start)}</b></div><span>+</span><div><small>In</small><b>${ins}</b></div><span>−</span><div><small>Out</small><b>${outs}</b></div><span>=</span><div><small>월말 인원</small><b>${start==null?'—':fmt(start+ins-outs)}</b></div></div>`+(events.length?table(['팀원','일자','구분','사유 · 후속 액션','담당자'],events.map(e=>`<tr><td><b>${esc(e.name)}${e.continuation?' · 계속':''}</b></td><td>${esc(e.date||'미입력')}</td><td>${tag(e.type,e.type==='In'?'green':e.type==='Out · 확인 필요'?'gold':'')}</td><td class="qc-detail">${esc(e.reason||'사유 미입력')}<br><small>${esc(e.action||'')}</small></td><td>${esc(e.owner||'미지정')}</td></tr>`)):empty('이달의 In · Out 기록이 없습니다.','이탈 사유는 확인된 내용을 Quit · Cut으로 구분해 기록합니다.'));}

function renderStories(type){const items=view().items||draft[type]||[],win=type==='wins';return items.length?`<div class="story-grid ${win?'wins-grid':'challenge-grid'}" style="--story-columns:${Math.min(3,items.length)}">${items.map((s,i)=>`<article class="story"><span class="story-index">${win?'WIN':'ACTION'} ${String(i+1).padStart(2,'0')}</span><h3>${esc(s.title||'제목 없음')}${s.continuation?' <small>· 계속</small>':''}</h3><dl>${(win?[['WIN',s.win],['HOW',s.how],...(s.next?[['NEXT',s.next]]:[])]:[['CAUSE',s.cause],['ACTION',s.action],['RESULT',s.result]]).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v||'아직 기록하지 않았습니다.')}</dd>`).join('')}</dl>${!win?`<div class="story-meta">${tag(s.owner||'담당 미지정')}${tag(s.due||'기한 미지정')}${tag(s.status||'계획','green')}</div>`:''}</article>`).join('')}</div>`:empty(win?'이번 달의 성공을 기록해 주세요.':'개선할 과제와 다음 액션을 기록해 주세요.',win?'무엇을 잘했는지, 어떻게 했는지, 다음에 무엇을 반복할지 남깁니다.':'원인 · 액션 · 담당자 · 기한을 함께 정리합니다.');}
function renderCallback(){const s=callbackSummary(),groups=view().items||callbackPages();return `<div class="kpis">${kpi('팀 전체 제출률',s.missing?'입력 중':pct(s.rate),'총 제출 ÷ 총 필드일수','featured')}${kpi('콜백싯 제출',fmt(s.submitted)+'회','입력된 제출 횟수 합계')}${kpi('총 필드일수',fmt(s.days)+'일','월간 기록 기준')}${kpi('미입력',s.missing+'명','빈칸과 0회는 다릅니다')}</div><div class="callback-teams">${groups.map(g=>{const {name,rows,all}=g,days=total(all.map(r=>r.days)),submitted=total(all.map(r=>r.submitted)),missing=all.filter(r=>r.days>0&&r.submitted==null).length;return `<section class="team-callback"><div class="team-callback-header"><div><h3>${esc(name)}${g.totalParts>1?` · ${g.part+1}/${g.totalParts}`:''}</h3><small>제출 ${submitted}회 / 필드 ${days}일 · ${all.length}명</small></div><div class="team-gauge">${bar(missing?null:ratio(submitted,days))}<strong>${missing?'입력 중':pct(ratio(submitted,days))}</strong></div></div>${table(['팀원','필드일수','콜백싯 제출횟수','제출률'],rows.map(r=>`<tr><td><b>${esc(r.name)}</b><span class="role">${esc(r.role||'')}</span></td><td>${r.days}일</td><td><input class="callback-input" type="number" min="0" max="${r.days}" step="1" inputmode="numeric" data-callback="${esc(r.id)}" value="${r.submitted??''}" placeholder="미입력" aria-label="${esc(r.name)} 콜백싯 제출 횟수" ${readOnly||presenting||!r.days?'disabled':''}></td><td><div class="callback-output">${bar(r.submitted==null?null:r.rate)}<b>${!r.days?'해당 없음':r.submitted==null?'미입력':pct(r.rate)}</b></div></td></tr>`))}</section>`;}).join('')||empty('필드 기록이 있는 팀원이 없습니다.','워크북 수치를 불러오면 팀별 제출률을 입력할 수 있습니다.','refresh')}</div><p class="table-note">미입력이 남으면 제출률은 입력 중으로 표시합니다. 모든 제출률은 총 제출 횟수 ÷ 총 필드일수입니다.</p>`;}

function renderGoals(){const g=draft.goals||{};return `<div class="learning-goals"><div class="goal-targets">${[['SALES',fmt(g.sales)+'+','건'],['INCOME',money(g.income),''],['SCORING HC',fmt(g.headcount),'명']].map(([label,value,unit])=>`<section><span>${label}</span><strong>${esc(value)}<small>${unit}</small></strong></section>`).join('')}</div><div class="goal-plans"><section><h3>집중 목표</h3><p>${esc(g.focus||'미입력')}</p></section><section><h3>실행 계획</h3><p>${esc(g.actions||'미입력')}</p></section></div><div class="goals-learning-list"><h3>Learning</h3>${(draft.learning||[]).map(x=>`<span>${esc(x.title)}</span>`).join('')}</div></div>`;}
function renderLearning(){const items=view().items||[];return items.length?`<div class="learn-lanes">${items.map(x=>`<section class="learn-lane"><div class="learn-labels">${tag(x.track)}${tag(x.period,x.period==='다음달 계획'?'green':'')}</div><article class="learn-item"><h3>${esc(x.title||'학습 기록')}${x.continuation?' · 계속':''}</h3><p>${esc(x.action||'실행 내용 미입력')}</p>${x.result?`<div class="learning-result"><small>배운 점 · 기대 결과</small><p>${esc(x.result)}</p></div>`:''}<footer>${esc([x.owner,x.due,x.status].filter(Boolean).join(' · ')||'담당자 · 일정 미입력')}</footer></article></section>`).join('')}</div>`:empty('학습과 다음 달 계획을 기록해 주세요.','IC · 트레이너 · 네트워킹 분야에서 회고와 계획을 각각 남깁니다.');}

const abilities=[['relate','릴레이트'],['booth','부스 컨트롤'],['pitch','피치 능력'],['objection','오브젝션 대응력'],['agreement','약정서 숙련도']];
function icMembers(){const people=new Map(allPeople().map(m=>[m.id,m])),selected=new Map();for(const node of draft.tree||[]){if(!node.planned&&/\bIC\b/i.test(node.role||'')){const p=people.get(node.id)||{},evidence=draft.icEvidence?.[node.id];selected.set(node.id,{...p,...node,...(p.teamManual?{team:p.team,teamManual:true}:{}),firstFive:p.firstFive?.length?p.firstFive:evidence?.firstFive||[],join:p.join||evidence?.join||'',currentTree:true});}}for(const id of Object.keys(draft.icPlans||{})){const person=people.get(id);if(person&&!selected.has(id)){const evidence=draft.icEvidence?.[id];selected.set(id,{...person,firstFive:person.firstFive?.length?person.firstFive:evidence?.firstFive||[],join:person.join||evidence?.join||'',currentTree:false});}}return M.inheritTeams([...selected.values()],draft.tree||[]);}

function renderIC(){const m=view().items?.[0];if(!m)return empty('IC 성장 플랜을 준비해 주세요.','현재 팀 트리의 IC 또는 명시적으로 선택한 팀원의 성장 플랜을 보여줍니다.');const p=draft.icPlans?.[m.id]||{},days=(p.firstDays?.length?p.firstDays.map(sales=>({date:'',sales})):m.firstFive||[]).slice(0,5),known=days.filter(d=>number(d.sales)!=null),sales=known.length?total(known.map(d=>d.sales)):null,avg=known.length?sales/known.length:null,people=icMembers(),index=people.findIndex(p=>p.id===m.id),monthly=(draft.members||[]).find(x=>x.id===m.id);return `<div class="ic-stage"><section class="ic-character-panel"><div class="ic-identity"><span class="eyebrow">${m.currentTree?'CURRENT TEAM · IC':'PERSONAL GROWTH PLAN'}</span><h2>${esc(m.name)}</h2><p>${esc(m.team||'팀 미지정')} · ${esc(m.role||'역할 미확인')}</p><span class="tag">평가 기록 ${abilities.filter(([key])=>number(p[key])!=null).length} / 5</span></div><div class="ic-first-days"><h4>실제 첫 5일 기록</h4><div class="five-days">${Array.from({length:5},(_,i)=>`<div title="${esc(days[i]?.date||'날짜별 자료 미확인')}"><small>D${i+1}</small><time>${esc(days[i]?.date?.slice(5)||'—')}</time><b>${fmt(days[i]?.sales)}</b></div>`).join('')}</div></div><div class="ic-evidence"><div><span>첫 5일 확인 성과</span><b><span data-counter>${fmt(sales)}</span><small>건</small></b></div><div><span>확인 일수 AVG</span><b data-counter>${avgFmt(avg)}</b></div><p>확인 ${known.length} / 5일 · ${known.length?(known.every(d=>d.date)?`${esc(known[0].date)} ~ ${esc(known.at(-1).date)}`:'일자 미기재'):'날짜별 자료 미확인'}</p>${monthly?`<p>${esc(monthName())} 월간 세일즈 ${fmt(metrics(monthly).sales)}건 · 필드 ${fmt(monthly.days)}일</p>`:`<p>${esc(monthName())} 성과 집계에 포함되지 않은 팀원</p>`}</div></section><section class="ic-stats-panel"><div class="ic-stats-heading"><div><span class="eyebrow">GROWTH ABILITIES</span><h3>다섯 가지 역량</h3></div><span class="ability-scale">${p.scorePercent?'직접 평가 · 0–100%':'직접 평가 · 0–5'}</span></div><div class="ability-list">${abilities.map(([key,label])=>`<div class="ability"><span>${label}${key==='pitch'?'<small>Tone of Voice · Body Language</small>':''}</span>${bar(p[key],5)}<b>${p[key]==null?'평가 대기':p.scorePercent?fmt(p[key]*20)+'%':fmt(p[key],2)+'/5'}</b></div>`).join('')}</div><div class="ic-focus"><b>집중 역량</b><p>${esc(p.focus||'아직 설정하지 않았습니다.')}</p></div><div class="ic-plan-days">${[1,2,3].map(n=>`<div><b>DAY ${n}</b><p>${esc(p['day'+n]?.length>70?'상세 계획은 이어지는 페이지에서 확인합니다.':p['day'+n]||'계획 미입력')}</p></div>`).join('')}</div></section></div><div class="ic-pagination"><button data-action="ic-prev" ${index<=0?'disabled':''} aria-label="이전 팀원">←</button><span>${index+1} / ${people.length} · ${esc(m.name)}</span><button data-action="ic-next" ${index>=people.length-1?'disabled':''} aria-label="다음 팀원">→</button>${!readOnly&&!presenting?`<button data-action="ic-plan" data-id="${esc(m.id)}">역량 · 계획 편집</button>`:''}</div>`;}

function renderTree(){if(!view().treeRows)return renderTreeDiagram();const items=view().items||[],tree=draft.tree||[];return `<div class="tree-head"><p class="tree-legend">이달의 팀 관계 · 리더 연결을 함께 표시합니다.</p>${!readOnly&&!presenting?'<button data-action="tree-add">＋ 팀원 추가</button>':''}</div>`+table(['팀원','역할','연결된 리더','팀','구분'],items.map(n=>`<tr><td><b>${esc(n.name)}</b></td><td>${esc(n.role||'')}</td><td>${esc(tree.find(p=>p.id===n.parent)?.name||'최상위')}</td><td>${esc(n.team||'미지정')}</td><td>${tag(n.planned?'추가 예정':'기존 팀원',n.planned?'gold':'')}</td></tr>`));}
function treeGroups(){const nodes=draft.tree||[],ids=new Set(nodes.map(n=>n.id));return nodes.filter(n=>nodes.some(c=>c.parent===n.id)||!n.parent||!ids.has(n.parent)).flatMap(leader=>{const children=nodes.filter(n=>n.parent===leader.id),sets=batches(children,4);return sets.map((children,part)=>({leader,children,part,parts:sets.length}));});}
function renderTreeDiagram(){const nodes=draft.tree||[],byId=new Map(nodes.map(n=>[n.id,n])),editable=!readOnly&&!presenting;if(!nodes.length)return empty('저장된 팀 관계가 없습니다.','워크북 원본과 비교한 뒤 이달의 팀 트리에 적용해 주세요.');const children=id=>nodes.filter(n=>n.parent===id),roots=nodes.filter(n=>!n.parent||!byId.has(n.parent)),rendered=new Set();const weight=(node,seen=new Set())=>{if(seen.has(node.id))return 1;const next=new Set(seen).add(node.id),kids=children(node.id).filter(n=>!next.has(n.id));return kids.length?total(kids.map(n=>weight(n,next))):1;};const branchColors=new Map();roots.forEach(root=>children(root.id).forEach((first,i)=>{const paint=node=>{if(branchColors.has(node.id))return;branchColors.set(node.id,['#2460d8','#8954c8','#16856f'][i%3]);children(node.id).forEach(paint);};paint(first);}));const branch=(node,depth)=>{if(rendered.has(node.id))return '';rendered.add(node.id);const parent=byId.get(node.parent),kids=children(node.id).filter(n=>!rendered.has(n.id));return `<li class="org-branch ${node.planned?'planned':''}" data-node-id="${esc(node.id)}" data-parent-id="${esc(node.parent||'')}" style="--branch-weight:${weight(node)};--org-accent:${branchColors.get(node.id)||'#243d61'}"><div class="org-person ${node.planned?'planned':''}" data-depth="${depth}"><span class="org-depth-label">${depth===0?'최상위':depth+'단계'}</span><h3>${esc(node.name)}</h3><small>${esc(node.role||'역할 미확인')}${node.planned?' · 추가 예정':''}</small>${node.team?`<p class="org-team">${esc(node.team)}</p>`:''}${editable?`<div class="org-actions"><button data-action="tree-edit" data-id="${esc(node.id)}" aria-label="${esc(node.name)} 연결 편집">연결</button><button data-action="tree-add" data-id="${esc(node.id)}" aria-label="${esc(node.name)} 아래 팀원 추가">＋</button></div>`:''}</div>${kids.length?`<ul class="org-level" aria-label="${esc(node.name)} 직속 구성원">${kids.map(n=>branch(n,depth+1)).join('')}</ul>`:''}</li>`;};let content=roots.map(n=>branch(n,0)).join('');content+=nodes.filter(n=>!rendered.has(n.id)).map(n=>branch(n,0)).join('');return `<div class="tree-board"><div class="tree-summary"><p><b>${nodes.filter(n=>!n.planned).length}명</b>${nodes.some(n=>n.planned)?` · 추가 예정 ${nodes.filter(n=>n.planned).length}명`:''}</p>${editable?'<button data-action="tree-add">＋ 팀원 추가</button>':''}</div><div class="org-hierarchy"><ul class="org-level">${content}</ul></div></div>`;}
function renderPromotion(){const rows=view().items||draft.promotions||[];return rows.length?`<div class="promotion-grid">${rows.map(p=>{const m=(draft.members||[]).find(m=>m.id===p.memberId)||(draft.roster||[]).find(m=>m.id===p.memberId);return `<article class="promotion"><div class="promotion-top"><div class="avatar" aria-hidden="true">↗</div><div><span class="eyebrow">NEXT ROLE</span><h3>${esc(m?.name||p.name||'팀원 확인 필요')}</h3><div class="promotion-path">${esc(m?.role||'현재 역할 미확인')} → ${esc(p.targetRole||'목표 역할 미입력')}</div></div></div><div class="promotion-body"><p>${esc(p.action||'준비 액션을 기록해 주세요.')}</p><div class="checklist">${(p.checks||[]).map(c=>`<div class="check-row"><span class="check-dot ${c.done?'done':''}" aria-label="${c.done?'완료':'미완료'}">${c.done?'✓':''}</span><span>${esc(c.text)}</span></div>`).join('')}</div><div class="story-meta">${tag(p.due||'기한 미정')}${tag(p.status||'계획','green')}</div></div></article>`;}).join('')}</div>`:empty('승진 계획을 추가해 주세요.','실제 팀원을 선택하고 목표 역할 · 기한 · 준비 체크리스트를 기록합니다.');}
function renderOverview(){const t=totals(),r=recruiting(),cb=callbackSummary(),g=draft.goals||{};return `<div class="overview-hero"><div><span class="eyebrow">${esc(monthName())} · ${esc(draft.teamName||'Presence')}</span><h2>${Number(month.slice(5))}월 팀 성과 요약</h2><p>${esc((draft.wins||[])[0]?.title||'이달의 성과와 배움을 기록해 주세요.')}</p></div><div class="hero-score"><span>TEAM SALES</span><b data-counter>${fmt(t.sales)}</b></div></div><div class="overview-grid">${[['AVG',avgFmt(t.avg),'필드 '+fmt(t.days)+'일'],[t.incomeComplete===false?'확인된 인컴':'TEAM INCOME',money(t.incomeComplete===false?knownIncome():t.income),t.incomeComplete===false?`미입력 급여 기록 ${missingIncome()}개`:'입력 급여 주차 합계'],['REJECTION',pct(t.rate),'리섭 차감 후 기준'],['RECRUITING',fmt(r.starters)+'명',`부킹 ${fmt(r.booked)} · 쇼업 ${fmt(r.showup)}`],['CALLBACK',cb.missing?'입력 중':pct(cb.rate),`${cb.submitted}회 / ${cb.days}일 · 미입력 ${cb.missing}명`],['LEARNING',(draft.learning||[]).length+'개','회고와 다음 달 계획']].map(([title,note,sub])=>`<div class="overview-tile"><h3>${title}</h3><b data-counter>${esc(note)}</b><p>${esc(sub)}</p></div>`).join('')}</div><div class="goal-ribbon"><b>${nextMonthName()}<br>NEXT GOAL</b><div><p>세일즈 ${fmt(g.sales)}${g.income?' · 인컴 '+money(g.income):''}${g.headcount?' · HC '+fmt(g.headcount)+'명':''} · AVG ${avgFmt(g.avg)} · 스타터 ${fmt(g.recruit)}명 · 콜백 ${pct(g.callback)}</p><p class="goal-next-note">${g.focus||g.actions?'구체적인 집중 과제와 실행 계획은 다음 페이지로 이어집니다.':'다음 달 집중 과제를 기록해 주세요.'}</p></div></div>`;}

const renderers={cover:renderCover,contents:renderContents,sales:renderSales,weekly:renderWeekly,income:renderIncome,recruit:()=>renderRecruit(),rank:()=>renderRecruit(true),qc:renderQC,wins:()=>renderStories('wins'),challenges:()=>renderStories('challenges'),callback:renderCallback,learning:renderLearning,ic:renderIC,tree:renderTree,promotion:renderPromotion,overview:renderOverview};

function renderCanvas(){if(!draft)return;rebuildViews();const v=view(),intro=v.c<0,isSales=v.id==='sales'&&!v.kind,kicker=isSales?'팀원 성과':intro?(v.id==='cover'?'MONTHLY TEAM RECAP':'CONTENTS'):`${String(v.c+1).padStart(2,'0')} · ${chapters[v.c][0]}`,title=v.kind==='note'?v.noteTitle:v.title,subtitle=isSales?salesSubtitle():v.id==='income'&&totals().incomeComplete===false?'미입력 급여 주차는 0원으로 합산하지 않습니다.':desc[v.id]||'';$('#canvas').innerHTML=`<article class="slide slide-enter ${subtitle?'has-subtitle':'no-subtitle'}" data-view="${v.id}" data-page-kind="${v.kind||'main'}" aria-label="${esc(title)}">${v.id==='cover'?'':`<header class="slide-head"><div><span class="slide-kicker">${kicker}</span><h1>${esc(title)}${v.parts>1?`<span class="continued-badge">${v.part+1} / ${v.parts}</span>`:''}</h1>${subtitle?`<p class="slide-sub">${esc(subtitle)}</p>`:''}</div><div class="slide-logo">Presence<small>${esc(month)} · TEAM RECAP</small></div></header>`}<div class="slide-content">${v.kind==='goals'?renderGoals():v.kind==='note'?renderNote():renderers[v.id]()}</div><footer class="slide-foot">${isSales?`<span>${String(page+1).padStart(2,'0')} / ${views.length}</span>`:`<span>${esc(draft.teamName||'Presence')} · ${esc(monthName())}${draft.leader?' · '+esc(draft.leader):''}</span><span>${['income','weekly','overview'].includes(v.id)?'리젝은 리섭 차감 후 기준 · ':''}${String(page+1).padStart(2,'0')} / ${views.length}</span>`}</footer></article>`;$('#pageCount').textContent=`${String(page+1).padStart(2,'0')} / ${views.length} · ${title}`;$('#presentCount').textContent=`${page+1} / ${views.length}`;schedulePresentationFit();animateSlide();}
function render(){if(!draft)return;rebuildViews();const v=view();$('#month').value=month;if($('#editorLink'))$('#editorLink').href=`recap-keynote.html?month=${encodeURIComponent(month)}`;$('#docName').textContent=`${monthName()} · ${draft.teamName||'Team'} Recap${readOnly?' · 열람':' · 작성 및 저장'}`;$('#chapters').innerHTML=`<div class="rail-intro"><button class="chapter ${v.id==='cover'?'active':''}" data-action="page" data-index="0"><span class="no">↗</span><span><b>표지</b><small>OPENING</small></span></button><button class="chapter ${v.id==='contents'?'active':''}" data-action="page" data-index="1"><span class="no">☷</span><span><b>목차</b><small>CONTENTS</small></span></button></div>`+chapters.map(([en,ko],i)=>`<button class="chapter ${i===v.c?'active':''}" data-action="chapter" data-index="${i}" ${i===v.c?'aria-current="page"':''}><span class="no">${String(i+1).padStart(2,'0')}</span><span><b>${ko}</b><small>${en}</small></span></button>`).join('');$('#chapterLabel').textContent=v.c<0?'TEAM RECAP · OPENING':`${String(v.c+1).padStart(2,'0')} / ${chapters[v.c][0]}`;const tabs=v.c<0?INTRO:baseViews.filter(x=>x.c===v.c);$('#subnav').innerHTML=tabs.map(x=>`<button data-action="page" data-index="${views.findIndex(p=>p.id===x.id)}" class="${x.id===v.id?'active':''}" ${x.id===v.id?'aria-current="page"':''}>${x.title}</button>`).join('');renderCanvas();renderEditor();renderNotice();status();document.querySelectorAll('[data-action="save"],[data-action="edit"],[data-action="publish"],[data-action="refresh"],[data-action="import"]').forEach(b=>b.disabled=readOnly);}

function renderNotice(){const entries=[...noticeMessages];if(readOnly)entries.unshift(params.has('published')?'게시된 발표본을 열람하고 있습니다.':'저장된 리캡을 열람하고 있습니다.');$('#notice').hidden=!entries.length;$('#notice').innerHTML=entries.map(esc).join('<br>')+(readOnly?'<button data-action="open-draft">작성 및 저장으로</button>':'');}
function status(message){$('#saveStatus').textContent=message||(readOnly?(params.has('published')?'게시된 발표본':'저장된 리캡 · 열람 전용'):saving?'클라우드에 저장 중…':dirty?'수정됨 · 이 기기에 임시 보관':!draft?.revision?'워크북으로 불러온 새 리캡 · 아직 저장하지 않았습니다.':'클라우드 저장본 · '+(draft?.updatedAt?new Date(draft.updatedAt).toLocaleString('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'저장 전'));}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('on'),4500);}
function changed(){if(readOnly)return;dirty=true;changeVersion++;draft.updatedAt=Date.now();try{localStorage.setItem(backupKey(),JSON.stringify({draft,at:Date.now(),baseRevision:draft.revision||0}));}catch{status('수정됨 · 기기 임시 저장 실패, 클라우드에 저장해 주세요');}status();}
function bindField(path,label,type='textarea',help=''){const value=path.split('.').reduce((o,k)=>o?.[k],draft);return `<label>${esc(label)}${type==='textarea'?`<textarea data-bind="${path}">${esc(value||'')}</textarea>`:`<input data-bind="${path}" type="${type}" value="${esc(value??'')}" ${type==='number'?'min="0" step="any"':''}>`}${help?`<small class="mini">${esc(help)}</small>`:''}</label>`;}
function editorList(type,title,caption){const rows=records(type);return `<section class="editor-section"><h3>${title}</h3><div class="stack">${rows.map((r,i)=>`<div class="editor-list"><button data-action="edit-record" data-kind="${type}" data-id="${esc(r.id)}">${esc(caption?.(r)||r.title||r.name||`${title} ${i+1}`)}</button><button data-action="delete-record" data-kind="${type}" data-id="${esc(r.id)}" aria-label="${esc(r.title||r.name||title)} 삭제">×</button></div>`).join('')}</div><button class="primary" data-action="add-record" data-kind="${type}">＋ ${title} 추가</button></section>`;}
function renderEditor(){if(!draft||readOnly)return;const type=view().id;let content=`<section class="editor-section"><h3>리캡 문서</h3>${bindField('teamName','팀 이름','text')}${bindField('leader','작성자 · 리더','text')}${bindField('headline','이달의 한 문장','text')}<p class="mini">변경 내용은 이 기기에 임시 보관됩니다. 상단 저장으로 클라우드에 저장하세요.</p></section>`;
  if(['sales','weekly','income'].includes(type))content+=`<section class="editor-section"><h3>워크북 수치</h3><p class="mini">세일즈 · 필드 · 급여 · 리젝 수치는 워크북을 기준으로 불러옵니다.</p><button data-action="refresh">워크북 수치 새로 불러오기</button>${bindField('notes.sales','세일즈 회고')}</section>`;
  if(['recruit','rank'].includes(type))content+=editorList('recruiting','리쿠르팅 실적')+`<section class="editor-section">${bindField('notes.recruit','리쿠르팅 회고')}</section>`;
  if(type==='qc')content+=`<section class="editor-section">${bindField('qc.startCount','월초 인원','number')}${bindField('qc.inCount','In 집계','number')}${bindField('qc.outCount','Out 집계','number')}${bindField('qc.retentionWin','유지에 도움이 된 WIN')}${bindField('qc.trainingHow','교육 · 유지 활동 HOW')}</section>`+editorList('events','In · Out 기록');
  if(type==='wins')content+=editorList('wins','성과');
  if(type==='challenges')content+=editorList('challenges','개선 액션');
  if(type==='callback')content+=`<section class="editor-section"><h3>콜백싯 입력 · 팀 지정</h3><p class="mini">표에서 제출 횟수를 입력하세요. 0회와 미입력은 구분합니다. 팀 지정은 이달의 콜백 그룹에 적용하며 팀 트리와 별도로 보존합니다.</p>${(draft.members||[]).map(m=>`<button data-action="member-team" data-id="${esc(m.id)}">${esc(m.name)} · ${esc(m.team||'팀 미지정')}</button>`).join('')}</section>`;
  if(type==='learning')content+=editorList('learning','학습 · 실행 계획',r=>`${r.track} · ${r.title||r.period}`);
  if(type==='ic')content+=`<section class="editor-section"><h3>IC 성장 플랜</h3>${icMembers().map(m=>`<button data-action="ic-plan" data-id="${esc(m.id)}">${esc(m.name)} · 역량 & 3일 플랜</button>`).join('')}<button class="primary" data-action="ic-plan">＋ 팀원 성장 플랜</button><p class="mini">5개 역량을 각각 0~5로 평가합니다. 빈칸은 미평가로 유지합니다. 첫 5일 실적은 실제 날짜별 자료가 있는 경우에만 표시됩니다.</p></section>`;
  if(type==='tree')content+=`<section class="editor-section"><h3>이달의 팀 트리</h3><button class="primary" data-action="tree-add">＋ 팀원 추가</button>${(draft.tree||[]).map(n=>`<div class="editor-list"><button data-action="tree-edit" data-id="${esc(n.id)}">${esc(n.name)}${n.planned?' · 추가 예정':''}</button>${n.planned?`<button data-action="tree-delete" data-id="${esc(n.id)}" aria-label="${esc(n.name)} 예정 노드 삭제">×</button>`:''}</div>`).join('')}<button data-action="reload-tree">워크북 원본 비교 · 적용</button><p class="mini">팀 트리는 월별로 보존합니다. 원본 다시 불러오기는 이달에 편집한 관계와 추가 예정 노드를 초기화합니다.</p></section>`;
  if(type==='promotion')content+=editorList('promotions','승진 계획',r=>`${allPeople().find(m=>m.id===r.memberId)?.name||'팀원 확인 필요'} → ${r.targetRole||'목표 역할'}`);
  if(type==='overview')content+=`<section class="editor-section"><h3>${nextMonthName()} 목표</h3>${bindField('goals.sales','세일즈 목표','number')}${bindField('goals.avg','AVG 목표','number')}${bindField('goals.recruit','스타터 목표','number')}${bindField('goals.callback','콜백싯 제출률 목표 (%)','number')}${bindField('goals.focus','집중 과제')}${bindField('goals.actions','실행 계획')}</section>`;
  $('#editor').innerHTML=content;
}
function allPeople(){const map=new Map();[...(draft.tree||[]).filter(n=>!n.planned),...(draft.roster||[]),...(draft.members||[])].forEach(m=>{if(m.id)map.set(m.id,m)});return [...map.values()].sort((a,b)=>String(a.name).localeCompare(String(b.name),'ko'));}
function openModal(title,body,submit,button='적용'){dialogOrigin=document.activeElement;$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#dialogForm footer').hidden=!submit;$('#dialogForm button[type="submit"]').textContent=button;pendingModal=submit;$('#dialog').showModal();requestAnimationFrame(()=>$('#dialogBody input, #dialogBody select, #dialogBody textarea, #dialogBody button, #dialog .dialog-head button')?.focus());}
function restoreDialogFocus(){if(dialogOrigin?.isConnected&&!dialogOrigin.closest('[hidden]'))dialogOrigin.focus();else (editing?$('#inspector [data-action="close-edit"]'):$('[data-action="present"]'))?.focus();}
function closeModal(){$('#dialog').close();pendingModal=null;restoreDialogFocus();}
function field(name,label,value='',type='text',opts={}){const attrs=`name="${esc(name)}" ${opts.required?'required':''}`;let control;if(type==='select')control=`<select ${attrs}>${(opts.options||[]).map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select>`;else if(type==='textarea')control=`<textarea ${attrs}>${esc(value)}</textarea>`;else control=`<input ${attrs} type="${type}" value="${esc(value??'')}" ${type==='number'?`min="${opts.min??0}" ${opts.max!=null?`max="${opts.max}"`:''} step="${opts.step??1}"`:''}>`;return `<label class="${opts.wide?'span2':''}">${esc(label)}${control}${opts.help?`<small class="hint">${esc(opts.help)}</small>`:''}</label>`;}
function confirmAction(title,body,action,button='계속'){openModal(title,`<p class="form-intro">${esc(body)}</p>`,async()=>{await action();return true;},button);}
const statusOptions=['계획','진행 중','완료','보류'];
function editRecord(kind,recordId){if(readOnly||!draft)return;const original=records(kind).find(r=>r.id===recordId)||{id:newId()};const item=kind==='recruiting'?{...original,booked:original.booking??original.booked,starters:original.starter??original.starters}:original;let fields='',title='내용 편집';
  if(kind==='wins'){title='성과 & 성공 요인';fields=field('title','성과 제목',item.title,'text',{required:true,wide:true})+field('win','WIN · 어떤 성과가 있었나요?',item.win,'textarea',{wide:true})+field('how','HOW · 어떻게 만들었나요?',item.how,'textarea',{wide:true})+field('next','NEXT · 무엇을 반복할까요?',item.next,'textarea',{wide:true});}
  if(kind==='challenges'){title='챌린지 & 개선 액션';fields=field('title','개선 과제',item.title,'text',{required:true,wide:true})+field('cause','원인',item.cause,'textarea',{wide:true})+field('action','개선 액션',item.action,'textarea',{wide:true})+field('result','결과 · 확인 방법',item.result,'textarea',{wide:true})+field('owner','담당자',item.owner)+field('due','기한',item.due,'date')+field('status','상태',item.status||'계획','select',{options:statusOptions});}
  if(kind==='events'){title='팀원 In · Out';fields=field('name','팀원 이름',item.name,'text',{required:true})+field('date','일자',item.date,'date')+field('type','구분',item.type||'In','select',{options:['In','Quit','Cut','Out · 확인 필요']})+field('owner','담당자',item.owner)+field('reason','사유',item.reason,'textarea',{wide:true})+field('action','후속 액션',item.action,'textarea',{wide:true})+field('status','진행 상태',item.status||'계획','select',{options:statusOptions});}
  if(kind==='learning'){title='학습 & 성장 계획';fields=field('track','분야',item.track||'IC','select',{options:['IC','트레이너','네트워킹']})+field('period','구분',item.period||'지난달 회고','select',{options:['지난달 회고','다음달 계획']})+field('title','제목',item.title,'text',{required:true,wide:true})+field('action','실행 내용 · 방법',item.action,'textarea',{wide:true})+field('result','배운 점 · 기대 결과',item.result,'textarea',{wide:true})+field('owner','담당자',item.owner)+field('due','기한',item.due,'date')+field('status','상태',item.status||'계획','select',{options:statusOptions});}
  if(kind==='recruiting'){title='리쿠르팅 실적';fields=field('name','팀원',item.name,'select',{required:true,wide:true,options:[['','팀원 선택'],...allPeople().map(m=>[m.name,`${m.name} · ${m.role||''}`])]})+field('booked','부킹',item.booked??0,'number')+field('showup','쇼업',item.showup??0,'number')+field('starters','스타터',item.starters??0,'number');}
  if(kind==='promotions'){title='승진 계획';fields=field('memberId','팀원',item.memberId,'select',{required:true,wide:true,options:[['','팀원 선택'],...allPeople().map(m=>[m.id,`${m.name} · ${m.role||''}`])]})+field('targetRole','목표 역할',item.targetRole,'text',{required:true})+field('due','목표 기한',item.due,'date')+field('status','상태',item.status||'계획','select',{options:statusOptions})+field('action','준비 액션 · 마일스톤',item.action,'textarea',{wide:true})+field('checklist','체크리스트 · 한 줄에 하나', (item.checks||[]).map(c=>`${c.done?'[x]':'[ ]'} ${c.text}`).join('\n'),'textarea',{wide:true,help:'완료한 항목은 [x], 준비 중인 항목은 [ ]로 시작해 주세요.'});}
  openModal(title,`<div class="form-grid">${fields}</div>`,data=>{const out={...item,...data};if(kind==='recruiting'){for(const k of ['booked','showup','starters'])out[k]=number(data[k]);if(out.showup>out.booked||out.starters>out.showup)throw new Error('부킹 ≥ 쇼업 ≥ 스타터가 되도록 수치를 확인해 주세요.');out.booking=out.booked;out.starter=out.starters;const other=records(kind).find(r=>r.id!==out.id&&r.name===out.name);if(other)throw new Error('이 팀원의 실적이 이미 있습니다. 기존 기록을 편집해 주세요.');}if(kind==='promotions'){out.checks=data.checklist.split('\n').map(t=>t.trim()).filter(Boolean).map(t=>({text:t.replace(/^\[[ xX]\]\s*/,''),done:/^\[[xX]\]/.test(t)}));delete out.checklist;}const rows=[...records(kind)];const i=rows.findIndex(r=>r.id===item.id);if(i<0)rows.push(out);else rows[i]=out;setRecords(kind,rows);changed();render();return true;});
}
function memberTeam(memberId){const member=draft.members.find(m=>m.id===memberId);if(!member)return;openModal(`${member.name} · 팀 지정`,field('team','이달의 팀 이름',member.team||'','text',{required:true}),data=>{member.team=data.team.trim();const person=(draft.roster||[]).find(m=>m.id===memberId);if(person)person.team=member.team;member.teamManual=true;changed();render();return true;});}
function icPlan(memberId){if(readOnly||!draft)return;const member=allPeople().find(m=>m.id===memberId);if(!member){openModal('성장 플랜 팀원 선택',field('memberId','팀원','','select',{required:true,options:[['','팀원 선택'],...allPeople().map(m=>[m.id,`${m.name} · ${m.role||''}`])]}),data=>{closeModal();icPlan(data.memberId);return false;});return;}const p=draft.icPlans?.[member.id]||{};openModal(`${member.name} · IC 성장 플랜`,`<p class="form-intro">역량은 0~5로 평가합니다. 판단하지 않은 항목은 비워 두세요.</p><div class="form-grid">${abilities.map(([key,label])=>field(key,label,p[key],'number',{max:5,help:key==='pitch'?'Tone of Voice · Body Language':''})).join('')}${field('focus','집중 역량',p.focus,'textarea',{wide:true})}${[1,2,3].map(n=>field(`day${n}`,`DAY ${n} · 목표와 실행`,p[`day${n}`],'textarea',{wide:true})).join('')}</div>`,data=>{abilities.forEach(([key])=>data[key]=number(data[key]));draft.icPlans??={};draft.icPlans[member.id]=data;changed();render();return true;});}
function treeAdd(parentId=''){if(readOnly||!draft)return;openModal('어떤 팀원을 추가할까요?',`<div class="choice-grid step-enter"><button type="button" class="choice" data-action="tree-choice-existing" data-id="${esc(parentId)}"><b>기존 팀원 추가</b><span>워크북 팀원을 선택하고<br>연결할 리더를 지정합니다.</span></button><button type="button" class="choice planned" data-action="tree-choice-planned" data-id="${esc(parentId)}"><b>New IC 추가 예정</b><span>이름과 리더를 지정해<br>다음 팀 구성을 계획합니다.</span></button></div>`,null);}
function treePeople(){return M.workbookTree(liveSource?.state||{},draft.tree||[]).filter(m=>!m.planned);}
function treeEditor(nodeId,planned=false,parentId=''){const node=(draft.tree||[]).find(n=>n.id===nodeId),isPlanned=node?node.planned:planned;const selectedParent=node?.parent||parentId;closeModal();const parents=(draft.tree||[]).filter(n=>n.id!==nodeId);const people=treePeople();if(node&&!node.planned&&!people.some(p=>p.id===(node.memberId||node.id)))people.push({...node,id:node.memberId||node.id});openModal(node?'팀원 연결 편집':isPlanned?'New IC 추가 예정':'기존 팀원 추가',`<div class="form-grid">${isPlanned?field('name','예정 팀원 이름',node?.name||'New IC','text',{required:true,wide:true}):field('memberId','기존 팀원',node?.memberId||node?.id||'','select',{required:true,wide:true,options:node?[[node.memberId||node.id,`${node.name} · ${node.role||''}`]]:[['','팀원 선택'],...people.map(m=>[m.id,`${m.name} · ${m.role||''}`])]})}${field('parent','연결할 리더',selectedParent,'select',{wide:true,options:[['','최상위에 배치'],...parents.map(n=>[n.id,`${n.name} · ${n.role||''}`])]})}</div><p class="form-intro" style="margin-top:18px">TL 이외의 트레이너에게도 연결할 수 있습니다. 월별 리캡의 팀 트리만 바뀝니다.</p>`,data=>{const actual=isPlanned?null:people.find(m=>m.id===data.memberId);if(!isPlanned&&!actual)throw new Error('기존 팀원을 선택해 주세요.');const existing=node||(!isPlanned?(draft.tree||[]).find(n=>n.id===actual.id||n.memberId===actual.id||n.name===actual.name):null);const next={...(existing||{}),id:existing?.id||(isPlanned?newId():actual.id),name:isPlanned?data.name.trim():actual.name,role:isPlanned?'IC':actual.role,team:isPlanned?'':actual.team,planned:isPlanned,parent:data.parent||null};if(actual)next.memberId=actual.id;let cursor=next.parent;const seen=new Set([next.id]);while(cursor){if(seen.has(cursor))throw new Error('팀 관계가 순환하지 않도록 리더를 다시 선택해 주세요.');seen.add(cursor);cursor=(draft.tree||[]).find(n=>n.id===cursor)?.parent;}draft.tree??=[];const i=draft.tree.findIndex(n=>n.id===next.id);if(i<0)draft.tree.push(next);else draft.tree[i]=next;changed();render();return true;});}

function validateDraft(candidate){if(candidate&&typeof candidate==='object'){for(const key of ['members','tree','roster','weeks','events','wins','challenges','learning','promotions']){if(!Array.isArray(candidate[key]))throw new Error(key+' 항목의 목록 형식을 확인해 주세요.');if(candidate[key].some(row=>!row||typeof row!=='object'||Array.isArray(row)))throw new Error(key+' 항목의 내용 형식을 확인해 주세요.');}for(const key of ['callbacks','qc','icPlans','goals','notes'])if(!candidate[key]||typeof candidate[key]!=='object'||Array.isArray(candidate[key]))throw new Error(key+' 항목의 형식을 확인해 주세요.');if(!Array.isArray(candidate.recruiting)&&(!candidate.recruiting||!Array.isArray(candidate.recruiting.rows)))throw new Error('리쿠르팅 목록 형식을 확인해 주세요.');for(const p of candidate.promotions)if(!Array.isArray(p.checks)||p.checks.some(c=>!c||typeof c.text!=='string'||typeof c.done!=='boolean'))throw new Error('프로모션 체크리스트 형식을 확인해 주세요.');for(const p of Object.values(candidate.icPlans))if(!p||typeof p!=='object'||Array.isArray(p))throw new Error('IC 성장 플랜 형식을 확인해 주세요.');}if(!candidate||candidate.version!==1||!/^\d{4}-\d{2}$/.test(candidate.month||'')||!Array.isArray(candidate.members)||!Array.isArray(candidate.tree))throw new Error('지원하는 Team Recap JSON 형식이 아닙니다.');if(M.validate){const result=M.validate(candidate);if(result===false)throw new Error('리캡 데이터 형식을 확인해 주세요.');if(Array.isArray(result)&&result.length)throw new Error(result.join('\n'));if(result?.ok===false)throw new Error((result.errors||['리캡 데이터 검증 실패']).join('\n'));}return candidate;}
async function makeLoaded(result){liveSource=result;noticeMessages=result.warnings||[];if(readOnly){const snapshot=params.has('published')?(result.published?.keynote||result.published?.snapshot||result.published?.draft||result.published):result.saved;if(!snapshot)throw new Error(params.has('published')?'이달에 게시된 발표본이 없습니다.':'이달에 저장된 리캡이 없습니다. 작성 및 저장 페이지에서 먼저 저장해 주세요.');return M.makeDraft({},month,snapshot);}if(result.saved)return M.makeDraft(result.state,month,result.saved.draft||result.saved);return M.makeDraft(result.state,month,result.legacy);}
async function loadMonth(next){const token=++loadToken;month=next;draft=null;$('#editor').innerHTML='';document.querySelectorAll('[data-action="save"],[data-action="edit"]').forEach(b=>b.disabled=true);$('#month').value=month;$('#canvas').innerHTML='<div class="slide"><div class="empty"><strong>리캡을 불러오는 중…</strong><span>월별 리캡 기록을 확인하고 있습니다.</span></div></div>';status('월별 기록 불러오는 중…');try{const result=await (isViewer?api.read(month,params.has('published')):api.load(month));if(token!==loadToken)return;draft=await makeLoaded(result);if(token!==loadToken)return;draft.month=month;draft.callbacks??={};draft.qc??={};draft.goals??={};draft.notes??={};draft.icPlans??={};dirty=false;const url=new URL(location.href);url.searchParams.set('month',month);history.replaceState(null,'',url);render();if(!readOnly){let backup;try{backup=JSON.parse(localStorage.getItem(backupKey())||'null');}catch{}if(backup?.draft&&backup.draft.month===month&&Number(backup.at)>Number(draft.updatedAt||0)){confirmAction('이 기기에 저장된 수정본이 있습니다.','클라우드 저장 이후 편집한 내용이 이 기기에 남아 있습니다. 복구하면 현재 리캡에 적용되며, 클라우드에는 저장 버튼을 눌러야 반영됩니다.',()=>{draft=validateDraft(backup.draft);dirty=true;render();toast('기기 수정본을 복구했습니다.');},'수정본 복구');}}if(params.has('present')&&!presenting)setPresent(true);}catch(error){noticeMessages=[error.message||'리캡을 불러오지 못했습니다.'];$('#canvas').innerHTML=`<div class="slide">${empty('리캡을 불러오지 못했습니다.',error.message||'연결 상태를 확인해 주세요.','retry-load')}</div>`;renderNotice();status('불러오기 실패 · 다시 시도해 주세요');}}
async function save(){if(!draft||readOnly||saving)return false;try{validateDraft(draft);saving=true;status();const savingDraft=draft,sent=copy(draft),sentVersion=changeVersion,revision=Number(draft.revision)||0;const saved=await api.save(sent,revision);if(draft!==savingDraft){toast(`${sent.month} 리캡을 저장했습니다.`);return true;}draft.revision=saved?.revision??saved?.draft?.revision??revision+1;if(changeVersion===sentVersion){draft.updatedAt=saved?.updatedAt||saved?.draft?.updatedAt||Date.now();dirty=false;try{localStorage.removeItem(backupKey());}catch{}}else{changed();}toast('리캡을 클라우드에 저장했습니다.');return true;}catch(error){status('저장 실패 · 수정 내용은 이 기기에 보관');toast(error.message||'저장하지 못했습니다. 수정 내용은 유지됩니다.');noticeMessages=[error.message||'저장하지 못했습니다. 연결 상태를 확인한 뒤 다시 저장해 주세요.'];renderNotice();return false;}finally{saving=false;status();}}

async function auditTreeSource(){if(readOnly||!draft)return;openModal('워크북 팀 관계 확인','<p class="form-intro">현재 워크북의 팀 구성을 확인하고 있습니다.</p>',null);try{const source=await api.auditTree();if(!$('#dialog').open||$('#dialogTitle').textContent!=='워크북 팀 관계 확인')return;const audit=M.workbookTreeAudit(source.state,draft.tree);const notices=[...(source.warnings||[]),...(audit.warnings||[]),...(audit.errors||[])];const rows=(audit.changes||[]).map(change=>{const before=change.before,after=change.after;return `<tr><td><b>${esc(change.name)}</b><br>${esc(change.type==='added'?'추가':change.type==='removed'?'제외':'변경')}</td><td>${esc(before?[before.role,before.parent||'최상위',before.team||'팀 라벨 없음'].join(' · '):'없음')}</td><td>${esc(after?[after.role,after.parent||'최상위',after.team||'팀 라벨 없음'].join(' · '):'없음')}</td></tr>`;});const body=`<div class="audit-summary"><p class="form-intro">워크북 기준 ${audit.nodes?.length||0}명 · 이달의 저장된 트리와 비교합니다. 팀 라벨은 각 리더가 직접 이끄는 팀 이름이며, 상위 리더 연결과 별도로 확인합니다.</p>${notices.length?`<div class="notice">${notices.map(esc).join('<br>')}</div>`:''}${rows.length?table(['팀원 · 변경','현재 리캡 · 역할/리더/팀','워크북 · 역할/리더/팀'],rows):'<p class="form-intro">확인된 차이가 없습니다.</p>'}<p class="form-intro">적용하면 이달의 리캡 팀 트리만 바뀝니다. 수동 연결과 추가 예정 노드는 원본 관계로 교체됩니다. 워크북 인사 정보는 변경하지 않습니다.</p></div>`;closeModal();openModal('워크북 팀 관계 비교',body,audit.canApply?()=>{draft.tree=copy(audit.nodes);draft.treeSource={status:'verified',source:audit.source,sourceAt:audit.sourceAt,warnings:audit.warnings||[]};liveSource={...liveSource,state:{...(liveSource?.state||{}),...source.state}};if(M.icEvidenceFrom)draft.icEvidence={...(draft.icEvidence||{}),...M.icEvidenceFrom(liveSource.state,audit.nodes)};changed();render();toast('검증된 워크북 팀 관계를 이달의 리캡에 적용했습니다.');return true;}:null,'검증된 트리 적용');}catch(error){$('#dialogBody').innerHTML=`<p class="notice">${esc(error.message||'워크북 팀 관계를 확인하지 못했습니다. 저장된 트리는 유지합니다.')}</p>`;}}

async function refreshSource(treeOnly=false){if(readOnly||!draft)return;confirmAction(treeOnly?'워크북 원본 트리 다시 불러오기':'워크북 수치 새로 불러오기',treeOnly?'워크북의 현재 팀 관계를 다시 불러옵니다. 이달에 수동으로 변경한 연결과 추가 예정 노드는 초기화됩니다.':'최신 워크북의 세일즈 · 필드 · 급여 · 팀원 정보를 다시 불러옵니다. 작성한 회고와 계획, 콜백싯 입력, 팀 트리는 보존합니다.',async()=>{const result=await api.load(month);const fresh=await M.makeDraft(result.state,month);if(treeOnly)draft.tree=copy(fresh.tree||[]);else{const oldCallbacks=draft.callbacks||{},oldMembers=draft.members||[],callbacks={};(fresh.members||[]).forEach(m=>{const old=oldMembers.find(o=>o.id===m.id)||oldMembers.find(o=>o.name===m.name);callbacks[m.id]=oldCallbacks[m.id]??(old?oldCallbacks[old.id]:null)??null;});const plans={};(fresh.members||[]).forEach(m=>{const old=oldMembers.find(o=>o.id===m.id)||oldMembers.find(o=>o.name===m.name);if(old?.teamManual){m.team=old.team;m.teamManual=true;const r=(fresh.roster||[]).find(r=>r.id===m.id);if(r)r.team=old.team;}if(draft.icPlans?.[m.id]||old&&draft.icPlans?.[old.id])plans[m.id]=draft.icPlans[m.id]||draft.icPlans[old.id];});draft.icPlans={...draft.icPlans,...plans};draft.members=fresh.members;draft.weeks=fresh.weeks;draft.roster=fresh.roster;draft.callbacks=callbacks;draft.sourceAt=fresh.sourceAt||Date.now();noticeMessages=result.warnings||[];}liveSource=result;changed();render();toast(treeOnly?'워크북 팀 관계를 다시 불러왔습니다.':'최신 워크북 수치를 불러왔습니다.');},'불러오기');}
function setEditing(value){if(readOnly||!draft)return;editing=value;document.body.classList.toggle('editing',value);$('[data-action="edit"]').setAttribute('aria-expanded',String(value));if(value)requestAnimationFrame(()=>$('#inspector [data-action="close-edit"]').focus());else $('[data-action="edit"]')?.focus();}
function navigate(index){page=(index+views.length)%views.length;render();if(editing)$('#inspector').scrollTop=0;}
function setPresent(value){presenting=value;if(value){setEditing(false);$('#docMenu').hidden=true;}document.body.classList.toggle('presenting',value);$('#presentControls').hidden=!value;renderCanvas();if(!value&&document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});if(value)$('#presentControls button').focus();else $('[data-action="present"]').focus();}
async function openViewer(){if(!draft)return;if((dirty||!draft.revision)&&!await save())return;location.href=`recap-view.html?month=${encodeURIComponent(month)}`;}
let exportingPptx=false;
async function downloadPptx(){if(!draft||exportingPptx)return;rebuildViews();const snapshot={draft:copy(draft),views:copy(views),month},unsaved=!readOnly&&(dirty||!draft.revision),button=$('[data-action="export-pptx"]');exportingPptx=true;if(button){button.disabled=true;button.textContent='PPTX 생성 중…';}toast(unsaved?'현재 편집 내용으로 PPTX를 만듭니다. 클라우드 저장은 저장 버튼을 사용하세요.':'리캡 PPTX를 만들고 있습니다.');try{const {exportPptx}=await import('./pptx-export.js?v=20261009-pptx-4');await exportPptx(snapshot);toast(unsaved?'현재 편집 내용의 PPTX를 내려받았습니다.':'저장된 리캡 PPTX를 내려받았습니다.');}finally{exportingPptx=false;if(button){button.disabled=false;button.textContent='리캡 PPTX 다운로드';}}}
async function action(button){const {action:act,id,kind,index}=button.dataset;if(readOnly&&!['page','chapter','prev','next','ic-prev','ic-next','present','exit-present','fullscreen','menu','close-dialog','retry-load','open-draft','export','export-pptx','logout'].includes(act))return;switch(act){case 'save':await save();break;case 'page':navigate(Number(index));break;case 'chapter':navigate(views.findIndex(v=>v.c===Number(index)));break;case 'ic-prev':case 'ic-next':{const list=views.map((v,i)=>({v,i})).filter(x=>x.v.id==='ic'&&!x.v.kind),at=list.findIndex(x=>x.i===page),next=list[at+(act==='ic-next'?1:-1)];if(next)navigate(next.i);break;}case 'prev':navigate(page-1);break;case 'next':navigate(page+1);break;case 'edit':setEditing(!editing);break;case 'close-edit':setEditing(false);break;case 'present':if(isViewer)setPresent(true);else await openViewer();break;case 'exit-present':setPresent(false);break;case 'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen?.();break;case 'menu':$('#docMenu').hidden=!$('#docMenu').hidden;button.setAttribute('aria-expanded',String(!$('#docMenu').hidden));if(!$('#docMenu').hidden)$('#docMenu button').focus();break;case 'close-dialog':closeModal();break;case 'retry-load':await loadMonth(month);break;case 'open-draft':{const url=new URL('recap-keynote.html',location.href);url.searchParams.set('month',month);location.href=url;break;}case 'add-record':editRecord(kind);break;case 'edit-record':editRecord(kind,id);break;case 'delete-record':confirmAction('기록 삭제','선택한 기록을 이달의 리캡에서 삭제합니다.',()=>{setRecords(kind,records(kind).filter(r=>r.id!==id));changed();render();},'삭제');break;case 'member-team':memberTeam(id);break;case 'ic-plan':icPlan(id);break;case 'tree-add':treeAdd(id);break;case 'tree-choice-existing':treeEditor(null,false,id);break;case 'tree-choice-planned':treeEditor(null,true,id);break;case 'tree-edit':treeEditor(id);break;case 'tree-delete':{const node=draft.tree.find(n=>n.id===id);if(!node?.planned)break;confirmAction('추가 예정 노드 삭제',`${node.name} 노드를 삭제합니다. 연결된 하위 노드는 상위 리더에게 연결됩니다.`,()=>{draft.tree.forEach(n=>{if(n.parent===id)n.parent=node.parent||null});draft.tree=draft.tree.filter(n=>n.id!==id);changed();render();},'삭제');break;}case 'refresh':await refreshSource();break;case 'reload-tree':await auditTreeSource();break;case 'export-pptx':await downloadPptx();break;case 'export':{const blob=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Presence-Team-Recap-${month}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('리캡 JSON 파일을 내보냈습니다.');break;}case 'import':$('#importFile').click();break;case 'publish':confirmAction('발표본 게시','현재 리캡을 저장하고 이달의 발표본으로 게시합니다. 이후 편집은 재게시하기 전까지 발표본에 반영되지 않습니다.',async()=>{if(!(await save()))return;await api.publish(copy(draft));toast('발표본을 게시했습니다.');},'저장하고 게시');break;case 'logout':if(dirty)confirmAction('로그아웃','현재 수정본은 이 기기에 남아 있습니다. 클라우드에 저장하려면 취소한 뒤 저장을 눌러 주세요.',async()=>{await api.logout();location.reload();},'로그아웃');else{await api.logout();location.reload();}break;}}

document.addEventListener('click',async e=>{const button=e.target.closest('button[data-action]');if(!button||button.disabled)return;try{if(!['menu','close-dialog'].includes(button.dataset.action)){$('#docMenu').hidden=true;$('[data-action="menu"]').setAttribute('aria-expanded','false');}await action(button);}catch(error){toast(error.message||'작업 중 오류가 발생했습니다.');}});
document.addEventListener('change',e=>{const path=e.target.dataset.bind;if(!path||!draft||readOnly)return;const parts=path.split('.');let obj=draft;parts.slice(0,-1).forEach(p=>{obj[p]??={};obj=obj[p]});const value=e.target.type==='number'?number(e.target.value):e.target.value;if(e.target.type==='number'&&value!=null&&(!Number.isFinite(value)||value<0)){e.target.setCustomValidity('0 이상의 숫자를 입력해 주세요.');e.target.reportValidity();return;}e.target.setCustomValidity('');obj[parts.at(-1)]=value;changed();renderCanvas();$('#docName').textContent=`${monthName()} · ${draft.teamName||'Team'} Recap`;});
document.addEventListener('input',e=>{const id=e.target.dataset.callback;if(!id||readOnly)return;const member=draft.members.find(m=>m.id===id);const value=number(e.target.value);if(value!=null&&(!Number.isInteger(value)||value<0||value>Number(member.days))){e.target.setCustomValidity(`0~${member.days} 사이의 정수를 입력해 주세요.`);e.target.reportValidity();return;}e.target.setCustomValidity('');draft.callbacks[id]=value;changed();renderCanvas();const target=[...document.querySelectorAll('[data-callback]')].find(el=>el.dataset.callback===id);if(target){target.replaceWith(e.target);e.target.focus();}});
$('#dialogForm').addEventListener('submit',async e=>{e.preventDefault();if(!pendingModal)return;const button=$('#dialogForm button[type="submit"]');button.disabled=true;try{const submit=pendingModal;const result=await submit(Object.fromEntries(new FormData(e.currentTarget)));if(result!==false&&pendingModal===submit)closeModal();}catch(error){let errorBox=$('#dialogError');if(!errorBox){errorBox=document.createElement('p');errorBox.id='dialogError';errorBox.className='notice';errorBox.setAttribute('role','alert');$('#dialogBody').append(errorBox);}errorBox.textContent=error.message||'입력 내용을 확인해 주세요.';errorBox.scrollIntoView({block:'nearest'});}finally{button.disabled=false;}});
