$('#month').addEventListener('change',e=>{const next=e.target.value;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(next)){e.target.value=month;return;}if(dirty){e.target.value=month;confirmAction('다른 월 리캡 열기','현재 수정본은 이 기기에 임시 보관됩니다. 다른 기기에서도 확인하려면 먼저 클라우드에 저장해 주세요.',()=>loadMonth(next),'다른 월 열기');}else loadMonth(next);});
$('#importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>1024*1024)throw new Error('JSON 파일은 1MB 이하로 가져와 주세요.');const raw=JSON.parse(await file.text());if(raw.month&&raw.month!==month)throw new Error(`${raw.month} 리캡입니다. 해당 월을 먼저 선택해 주세요.`);const imported=validateDraft(raw.version===1?raw:M.importLegacyConfirmed(raw,liveSource?.state||{},month));if(imported.month!==month)throw new Error(`${imported.month} 리캡입니다. 해당 월을 먼저 선택한 뒤 가져와 주세요.`);confirmAction('리캡 JSON 가져오기',`${file.name} · ${imported.month} · 팀원 ${imported.members.length}명. 이 파일의 내용으로 현재 월의 편집본을 교체합니다. 클라우드에는 저장 버튼을 눌러야 반영됩니다.`,()=>{const revision=draft.revision;draft=copy(imported);draft.revision=revision;changed();render();toast('JSON 내용을 가져왔습니다.');},'가져오기');}catch(error){toast(error.message||'JSON 파일을 읽지 못했습니다.');}});
document.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'&&draft&&!readOnly){e.preventDefault();save();return;}if(e.key==='Escape'){if($('#dialog').open)return;if(presenting)setPresent(false);else if(editing)setEditing(false);else{$('#docMenu').hidden=true;$('[data-action="menu"]').setAttribute('aria-expanded','false');$('[data-action="menu"]').focus();}return;}if(!$('#docMenu').hidden&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){const buttons=[...$('#docMenu').querySelectorAll('button:not(:disabled)')],at=buttons.indexOf(document.activeElement);e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(at+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();return;}if(!presenting||typing||$('#dialog').open)return;if(['ArrowRight','ArrowDown',' ','PageDown'].includes(e.key)){e.preventDefault();navigate(page+1);}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();navigate(page-1);}if(e.key==='Home'){e.preventDefault();navigate(0);}if(e.key==='End'){e.preventDefault();navigate(views.length-1);}});
let presentationFitFrame=0;
function schedulePresentationFit(){if(presentationFitFrame)cancelAnimationFrame(presentationFitFrame);presentationFitFrame=requestAnimationFrame(fitPresentation);}
function fitPresentation(){presentationFitFrame=0;const canvas=$('#canvas'),slide=canvas.querySelector('.slide'),frame=$('#canvasViewport'),wide=matchMedia('(min-width:761px)').matches;document.body.classList.toggle('viewer-fixed',isViewer&&wide&&!presenting);if(!canvas||!slide)return;if(!wide||(!presenting&&!isViewer)){canvas.removeAttribute('style');if(frame)frame.style.height='';slide.style.minHeight='';return;}canvas.style.width='1440px';canvas.style.height='810px';slide.style.minHeight='';if(presenting){if(frame)frame.style.height='';const controls=$('#presentControls').getBoundingClientRect(),availableHeight=Math.max(160,controls.top-32),scale=Math.min((window.innerWidth-48)/1440,availableHeight/810);canvas.style.transform='translateX(-50%) scale('+scale+')';canvas.style.top=(16+Math.max(0,(availableHeight-810*scale)/2))+'px';}else{const width=frame?.getBoundingClientRect().width||canvas.parentElement.clientWidth,scale=Math.min(1,width/1440);if(frame)frame.style.height=810*scale+'px';canvas.style.transform='translateX(-50%) scale('+scale+')';canvas.style.top='0px';}}
let motionGeneration=0;
function animateSlide(){const generation=++motionGeneration;if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;const canvas=$('#canvas');canvas.querySelector('.slide')?.animate([{opacity:.35,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(0,0,.3,1)'});canvas.querySelectorAll('.bar-fill,.sales-bar,.avg-fill,.weekly-fill').forEach((el,i)=>el.animate([{transform:el.classList.contains('weekly-fill')?'scaleY(0)':'scaleX(0)'},{transform:'scale(1)'}],{duration:700,delay:Math.min(i*35,210),easing:'cubic-bezier(0,0,.3,1)',fill:'backwards'}));canvas.querySelectorAll('.ability,.overview-tile,.rank-row-wide').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:240,delay:Math.min(i*55,330),easing:'cubic-bezier(0,0,.3,1)',fill:'backwards'}));const counters=[...canvas.querySelectorAll('.kpi b,[data-counter]')].map(el=>{const text=el.textContent,match=text.match(/^([^0-9-]*)([0-9,]+(?:\.[0-9]+)?)(.*)$/);if(!match)return null;const value=Number(match[2].replaceAll(',',''));return {el,text,value,prefix:match[1],suffix:match[3],digits:(match[2].split('.')[1]||'').length};}).filter(Boolean);const start=performance.now();function tick(now){if(generation!==motionGeneration)return;const progress=Math.min(1,(now-start)/700),ease=1-Math.pow(1-progress,3);for(const c of counters)if(c.el.isConnected)c.el.textContent=progress===1?c.text:c.prefix+(c.value*ease).toLocaleString('ko-KR',{minimumFractionDigits:c.digits,maximumFractionDigits:c.digits})+c.suffix;if(progress<1)requestAnimationFrame(tick);}requestAnimationFrame(tick);}
const presentationObserver=new ResizeObserver(schedulePresentationFit);presentationObserver.observe($('#canvas'));window.addEventListener('resize',schedulePresentationFit);document.addEventListener('fullscreenchange',schedulePresentationFit);document.fonts?.ready.then(schedulePresentationFit);$('#canvas').addEventListener('load',schedulePresentationFit,true);
let touchStart=null;$('#canvas').addEventListener('touchstart',e=>{if(presenting&&e.touches.length===1)touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});$('#canvas').addEventListener('touchend',e=>{if(!touchStart||!presenting)return;const t=e.changedTouches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;touchStart=null;if(Math.abs(dx)>75&&Math.abs(dx)>Math.abs(dy)*1.5)navigate(page+(dx<0?1:-1));},{passive:true});
