$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;$('#loginMsg').textContent='로그인 확인 중…';try{const candidate=await api.login($('#loginId').value.trim(),$('#loginPw').value);$('#loginPw').value='';await enter(candidate);}catch(error){$('#loginMsg').textContent=error.message||'로그인하지 못했습니다. 아이디와 비밀번호를 확인해 주세요.';}finally{button.disabled=false;}});
async function start(){if(isViewer&&!$('#canvasViewport')){const frame=document.createElement('div');frame.id='canvasViewport';frame.className='canvas-viewport';$('#canvas').before(frame);frame.append($('#canvas'));}if(!isViewer&&(params.has('published')||params.has('present')))return;if(!$('[data-action="export-pptx"]')){const button=document.createElement('button');button.dataset.action='export-pptx';button.textContent='리캡 PPTX 다운로드';$('#docMenu').prepend(button);}document.querySelectorAll('.archive-link,.login-card .text-link').forEach(a=>a.href='recap-library.html');if(!isViewer){$('[data-action="present"]').textContent='열람';}else{const link=$('#editorLink');if(link)link.href=`recap-keynote.html?month=${encodeURIComponent(month)}`;}try{api=typeof gateway==='function'?await gateway():gateway;const fullscreen=document.createElement('button');fullscreen.dataset.action='fullscreen';fullscreen.textContent='전체화면';$('#presentControls').append(fullscreen);const candidate=await api.restore();if(candidate)await enter(candidate);else $('#loginMsg').textContent='Presence 계정으로 로그인해 주세요.';}catch(error){$('#loginMsg').textContent=error.message||'저장된 로그인을 확인하지 못했습니다. 다시 로그인해 주세요.';}}
